-- 1. Add column with constant default (instantaneous metadata change in PG 11+)
ALTER TABLE users 
ADD COLUMN is_verified BOOLEAN NOT NULL DEFAULT false;

-- 2. Rename column (instant metadata change)
ALTER TABLE users 
RENAME COLUMN is_verified TO email_verified;

-- 3. Change column type using explicit cast expression
ALTER TABLE metrics 
ALTER COLUMN count TYPE BIGINT USING count::BIGINT;

-- 1. Fail fast rather than blocking every reader of the table
SET lock_timeout = '3s';
-- 1b. Never wait for an ACCESS EXCLUSIVE lock forever:
-- statement_timeout = '5min';

-- 2. Metadata-only: nullable, no default
ALTER TABLE users ADD COLUMN is_verified BOOLEAN;

-- 3. Backfill in batches to keep transactions short
UPDATE users
SET    is_verified = false
WHERE  is_verified IS NULL
  AND  id IN (SELECT id FROM users WHERE is_verified IS NULL LIMIT 5000);
-- repeat until 0 rows, or use the id-range pattern below
-- UPDATE users SET is_verified = false WHERE id BETWEEN 1 AND 100000 AND is_verified IS NULL;

-- 4. Now declare the default for new rows (no rewrite)
ALTER TABLE users ALTER COLUMN is_verified SET DEFAULT false;

-- 5. And finally enforce NOT NULL
ALTER TABLE users ALTER COLUMN is_verified SET NOT NULL;

-- Rename a column (instant) and change a type with an explicit cast
ALTER TABLE users RENAME COLUMN is_verified TO email_verified;
ALTER TABLE metrics ALTER COLUMN count TYPE BIGINT USING count::BIGINT;
ALTER TABLE metrics ALTER COLUMN count SET STATISTICS 1000;  -- better planner estimates
